function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(value){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value||0);}
function moneyExact(value){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(value||0);}
function initials(user){return ((user?.firstName?.[0]||'A')+(user?.lastName?.[0]||'')).toUpperCase();}
function plan(id){return PLANS[id]||PLANS.free;}
function qs(name){return new URLSearchParams(location.search).get(name)||'';}
function route(){return location.pathname.replace(/\/+$/,'')||'/';}
function toast(message,type=''){const el=document.createElement('div');el.className='toast '+type;el.textContent=message;toastRegion.appendChild(el);setTimeout(()=>el.remove(),3600);}
function setBusy(button,busy,label){if(!button)return;if(!button.dataset.label)button.dataset.label=button.textContent;button.disabled=busy;button.textContent=busy?(label||'Working…'):button.dataset.label;}

async function api(url,options={}){
  const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
  const data=await response.json().catch(()=>({}));
  if(!response.ok){const error=new Error(data.error||'Request failed');error.code=data.code;error.data=data;throw error;}
  return data;
}

function nitroMark(){return `<svg viewBox="0 0 24 24" width="17" height="17" fill="currentColor" aria-hidden="true"><path d="M13 2 3 14h7l-1 8 10-13h-7z"/></svg>`;}
function brand(){return `<a class="brand" href="/"><span class="brand-icon">${nitroMark()}</span><span>Nitro Outreach<small>Marketing platform</small></span></a>`;}
function publicNav(){return `<header class="topnav">${brand()}<nav class="nav-links"><a href="/#platform">Platform</a><a href="/audit">Free Audit</a><a href="/pricing">Pricing</a><a href="/#solutions">Solutions</a></nav><div class="nav-actions">${state.session?'<a class="btn btn-primary" href="/app">Open workspace</a>':'<a class="btn btn-ghost" href="/login">Log in</a><a class="btn btn-primary" href="/signup">Start free</a>'}</div></header>`;}
function footer(){return `<footer class="public-footer"><div class="footer-inner">${brand()}<span>© ${new Date().getFullYear()} Nitro Outreach. Built for small teams doing their own marketing.</span><span><a href="/pricing">Pricing</a> · <a href="/privacy">Privacy</a> · <a href="/terms">Terms</a></span></div></footer>`;}

function legalPage(type){
  const privacy=type==='privacy';
  document.title=(privacy?'Privacy Policy':'Terms of Service')+' — Nitro Outreach';
  const sections=privacy?[
    ['Information we collect','Account and contact details you provide; workspace content and files; campaign, website, social, outreach, and billing activity; device, log, and usage information; and information from services you choose to connect. Payment card details are handled by Stripe and are not stored in full by Nitro.'],
    ['How we use information','To provide, secure, support, and improve Nitro; personalize your workspace; process subscriptions; send service messages and requested reports; prevent abuse; and comply with law. We do not sell personal information.'],
    ['AI and connected services','Content you submit may be sent to AI and infrastructure providers solely to deliver requested features. Connected platforms such as Instagram, email, SMS, and payment providers process data under their own terms and your selected permissions.'],
    ['Sharing','We share information with service providers that help operate Nitro, when you direct us to connect or publish through another service, to protect users and the service, or when legally required.'],
    ['Retention and security','We keep information only as long as reasonably needed for the service, legal obligations, disputes, and security. We use reasonable safeguards, but no online service can guarantee absolute security.'],
    ['Your choices','You may update account information, disconnect integrations, unsubscribe from marketing messages, or request access, correction, or deletion by emailing hello@nitrooutreach.com. Some records may be retained when required by law or legitimate security needs.'],
    ['Children and changes','Nitro is not intended for children under 13. We may update this policy as the product changes and will post the revised effective date here.']
  ]:[
    ['Using Nitro','You must provide accurate account information, protect your login, and use Nitro only for lawful business purposes. You are responsible for activity in your workspace and for reviewing content before publishing or sending it.'],
    ['AI-generated content','AI output can be incomplete or incorrect and is not professional legal, financial, or medical advice. You must review claims, rights, accuracy, and suitability before use. Nitro does not guarantee a specific marketing, revenue, delivery, or campaign result.'],
    ['Outreach and platform rules','You are responsible for consent, opt-outs, contact-list rights, advertising disclosures, and compliance with email, SMS, privacy, intellectual-property, and connected-platform rules. Do not send spam, impersonate others, scrape unlawfully, or upload content you do not have the right to use.'],
    ['Plans, trials, and billing','Plan features, usage limits, credits, and prices are shown at checkout. Paid subscriptions renew until canceled. Trial and refund terms displayed during purchase control for that purchase. Payment processing is provided by Stripe.'],
    ['Ownership','You retain rights to content you submit. You give Nitro the limited permission needed to host, process, transform, and deliver that content through requested features. Nitro and its software, branding, and interface remain owned by Nitro Outreach and its licensors.'],
    ['Availability and termination','Features may change, experience interruptions, or depend on third-party services. We may suspend or terminate access for abuse, risk, nonpayment, or violations of these terms. You may stop using Nitro and cancel your subscription at any time.'],
    ['Disclaimers and liability','Nitro is provided on an “as is” and “as available” basis to the extent allowed by law. To the extent allowed by law, Nitro Outreach is not liable for indirect, incidental, special, consequential, or lost-profit damages.'],
    ['Contact and changes','Questions may be sent to hello@nitrooutreach.com. We may update these terms as Nitro evolves; continued use after an update means you accept the revised terms.']
  ];
  return `<div class="public-shell">${publicNav()}<main class="legal-page"><header><span class="eyebrow">${privacy?'PRIVACY':'LEGAL'}</span><h1>${privacy?'Privacy Policy':'Terms of Service'}</h1><p>Effective August 3, 2026 · Plain-language information for Nitro Outreach customers.</p></header><div class="legal-layout"><aside><a href="/privacy" class="${privacy?'active':''}">Privacy Policy</a><a href="/terms" class="${privacy?'':'active'}">Terms of Service</a><a href="mailto:hello@nitrooutreach.com">Contact us</a></aside><article>${sections.map((section,index)=>`<section><span>${String(index+1).padStart(2,'0')}</span><div><h2>${section[0]}</h2><p>${section[1]}</p></div></section>`).join('')}</article></div><div class="legal-note">These pages are intended to clearly describe Nitro’s current service. They do not override rights that cannot be waived under applicable law.</div></main>${footer()}</div>`;
}

